import{_ as o,c as a,o as l,ag as t}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"下載與媒體庫","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/downloads.md","filePath":"zh-TW/guide/downloads.md","lastUpdated":1791311600000}'),r={name:"zh-TW/guide/downloads.md"};function i(n,e,d,s,c,h){return l(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="下載與媒體庫" tabindex="-1">下載與媒體庫 <a class="header-anchor" href="#下載與媒體庫" aria-label="Permalink to &quot;下載與媒體庫&quot;">​</a></h1><p>nPlyr 可以把串流播放清單儲存為真實檔案，並讓你在下載完成前就開始觀看。你的歷程、書籤與下載內容都收錄在媒體庫中。</p><h2 id="下載-hls-播放清單" tabindex="-1">下載 HLS 播放清單 <a class="header-anchor" href="#下載-hls-播放清單" aria-label="Permalink to &quot;下載 HLS 播放清單&quot;">​</a></h2><p>當你將一個 <code>m3u8</code> 傳送給下載器時，nPlyr 會：</p><ol><li>取得主播放清單與子播放清單（驗證 HTTP 狀態，並確認回傳體是真正的 <code>#EXTM3U</code> 文件）。</li><li>下載每一個片段，拒絕空白或格式錯誤的片段行，從而讓 404 錯誤頁永遠不會被誤當成播放清單。</li><li>將片段重新封裝進 <strong>MP4</strong> 容器。</li></ol><h3 id="磁碟配置" tabindex="-1">磁碟配置 <a class="header-anchor" href="#磁碟配置" aria-label="Permalink to &quot;磁碟配置&quot;">​</a></h3><ul><li>下載中：<code>&lt;name&gt;.temp/</code></li><li>完成後：重新命名為 <code>&lt;name&gt;/</code>，影片位於 <code>&lt;name&gt;/&lt;name&gt;.mp4</code>。</li><li>如果重新封裝失敗，原始的 <code>.ts</code> 會被保留並標記為 <code>completed</code>（而非 <code>failed</code>），以免資料遺失；單一片段失敗則標記為 <code>.failed</code>。</li><li>續傳依據標記檔案與清單工作——你可以暫停並繼續。</li></ul><blockquote><p>由<a href="/zh-TW/guide/browser.html">嗅探器</a>擷取的任何自訂請求<strong>標頭</strong>（referer、cookie、auth）都會被保留，並隨每個請求一併傳送。nPlyr 絕不偽造 referer 或 origin——只會在需要時補充 user-agent。</p></blockquote><h2 id="邊下邊播" tabindex="-1">邊下邊播 <a class="header-anchor" href="#邊下邊播" aria-label="Permalink to &quot;邊下邊播&quot;">​</a></h2><p>開啟此功能可<strong>邊下載邊觀看</strong>。nPlyr 透過一個本機回送伺服器提供已部分下載的檔案，並領先於下載前沿開始播放（<code>progressiveLookahead = 20</code> 個片段）。它<strong>預設關閉</strong>。</p><p>邊下邊播生效時：</p><ul><li>播放清單的金鑰（<code>#EXT-X-KEY</code>）行在交付前會被剝離，</li><li>播放器始終引用<strong>原始</strong>來源 URL（本機伺服器是透明的），</li><li>如果某個網域失敗，該網域會在本次工作階段中被列入黑名單，部分檔案會被取消並刪除，且 nPlyr 不會靜默改道。</li></ul><p>邊下邊播與去廣告互斥；只有在未使用邊下邊播時，去廣告才會接管。</p><h2 id="多清晰度與字幕" tabindex="-1">多清晰度與字幕 <a class="header-anchor" href="#多清晰度與字幕" aria-label="Permalink to &quot;多清晰度與字幕&quot;">​</a></h2><ul><li><strong>清晰度</strong>選擇作用於<strong>下載</strong>（下載前挑選變體；若不挑選，nPlyr 會短暫等待選擇，否則回退到最佳變體）。</li><li><strong>字幕</strong>會隨媒體一起下載，並儲存為片段暫存目錄中的 <code>subtitle.&lt;ext&gt;</code>，從而始終與檔案綁定。</li></ul><h2 id="媒體庫" tabindex="-1">媒體庫 <a class="header-anchor" href="#媒體庫" aria-label="Permalink to &quot;媒體庫&quot;">​</a></h2><p>媒體庫在一個可搜尋的位置匯集三樣東西：</p><ul><li><strong>歷程</strong>——你看過什麼、何時看過。</li><li><strong>書籤</strong>——你儲存的來源與項目。</li><li><strong>下載</strong>——透過下載器儲存的檔案。</li></ul><p>所有內容都可透過標題搜尋，並且媒體庫設計為在登入同一環境的 Mac 與 iPhone 之間同步。</p><h2 id="去廣告" tabindex="-1">去廣告 <a class="header-anchor" href="#去廣告" aria-label="Permalink to &quot;去廣告&quot;">​</a></h2><p>nPlyr 使用與 Chrome 擴充功能攔截清單相同的<strong>訂閱規則</strong>格式（即 hikerView 採用的方式）來封鎖廣告。你訂閱一個過濾清單，nPlyr 便會在瀏覽器中以及播放期間過濾請求。這與邊下邊播相互獨立——兩者同一時間只有一個生效。</p>',21)])])}const p=o(r,[["render",i]]);export{u as __pageData,p as default};
